insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('project-documents','project-documents',false,20971520,array['application/pdf','image/jpeg','image/png','image/webp']),('avatars','avatars',false,2097152,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy document_upload on storage.objects for insert to authenticated with check(bucket_id='project-documents' and exists(select 1 from public.documents d where d.storage_path=name and d.uploaded_by=auth.uid() and d.status='pending' and private.member(d.project_id) and not private.role(d.project_id,array['VIEWER']::public.project_role[])));
create policy document_read on storage.objects for select to authenticated using(bucket_id='project-documents' and exists(select 1 from public.documents d where d.storage_path=name and private.member(d.project_id)));
create policy avatar_write on storage.objects for insert to authenticated with check(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);
create policy avatar_read on storage.objects for select to authenticated using(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);
create function public.begin_upload(p_project uuid,p_entity_type text,p_entity_id uuid,p_document_type text,p_filename text,p_mime text,p_size bigint) returns jsonb language plpgsql security definer set search_path='' as $$ declare id uuid:=gen_random_uuid(); path text; begin if not private.member(p_project) or private.role(p_project,array['VIEWER']::public.project_role[]) then raise exception 'PERMISSION_DENIED'; end if; perform private.validate_entity(p_project,p_entity_type,p_entity_id); if p_document_type not in ('receipt','invoice','quotation','purchase_order','payment_proof','warranty','approval_document','generated_letter','report','other') or p_mime not in ('application/pdf','image/jpeg','image/png','image/webp') or p_size not between 1 and 20971520 then raise exception 'INVALID_FILE'; end if; path:='projects/'||p_project::text||'/'||p_document_type||'/'||id::text||'-'||regexp_replace(left(p_filename,100),'[^a-zA-Z0-9._-]','_','g'); insert into public.documents(id,project_id,entity_type,entity_id,document_type,storage_path,original_filename,mime_type,size_bytes,uploaded_by) values(id,p_project,p_entity_type,p_entity_id,p_document_type,path,p_filename,p_mime,p_size,auth.uid()); return jsonb_build_object('id',id,'path',path); end $$;
create function public.finish_upload(p_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare d public.documents; begin select * into d from public.documents where id=p_id for update; if d.uploaded_by is distinct from auth.uid() or not private.member(d.project_id) then raise exception 'PERMISSION_DENIED'; end if; if not exists(select 1 from storage.objects where bucket_id=d.storage_bucket and name=d.storage_path and (metadata->>'size')::bigint=d.size_bytes and metadata->>'mimetype'=d.mime_type) then raise exception 'UPLOAD_NOT_VERIFIED'; end if; update public.documents set status='ready' where id=p_id; if d.entity_type='generated_documents' then update public.generated_documents set storage_document_id=d.id where id=d.entity_id and project_id=d.project_id; end if; perform private.log(d.project_id,'document_uploaded',d.entity_type,d.entity_id); end $$;
create function public.save_generated(p_project uuid,p_template uuid,p_entity_type text,p_entity_id uuid,p_html text,p_snapshot jsonb) returns uuid language plpgsql security definer set search_path='' as $$ declare id uuid:=gen_random_uuid(); begin if not private.member(p_project) or private.role(p_project,array['VIEWER']::public.project_role[]) then raise exception 'PERMISSION_DENIED'; end if; perform private.validate_entity(p_project,p_entity_type,p_entity_id); if not exists(select 1 from public.document_templates where document_templates.id=p_template and (project_id=p_project or project_id is null)) then raise exception 'INVALID_TEMPLATE'; end if; insert into public.generated_documents(id,project_id,template_id,generated_by,entity_type,entity_id,reference_number,rendered_html,snapshot) values(id,p_project,p_template,auth.uid(),p_entity_type,p_entity_id,coalesce(p_snapshot->>'reference_number','PFM-'||to_char(now(),'YYYYMMDD')||'-'||left(id::text,8)),p_html,p_snapshot); perform private.log(p_project,'document_generated','generated_documents',id); return id; end $$;
insert into public.document_templates(template_type,name,subject_template,body_template,is_system_template) select lower(replace(t,' ','_')),t,t||' — {{project.name}}','<h1>'||t||'</h1><p>Date: {{today}} | Reference: {{reference_number}}</p><p>To: {{recipient}}</p><p>Project: {{project.name}} ({{project.code}})</p><p>{{prose}}</p><p>Amount: {{amount}}</p><p>Amount in words: {{amount_words}}</p>{{expenses}}<p>Funding received: {{funding.received}}</p><p>Project cash: {{project.cash}}</p><p>Available to spend: {{project.available_balance}}</p><p>Prepared by: {{member.name}} ({{member.email}})</p><p>I confirm that the listed amounts and supporting records relate to this project.</p><p>Signature: ____________________</p>',true from unnest(array['Reimbursement Request','Fund Request','Purchase Approval','Expense Statement','Project Financial Summary','Vendor Payment Request','Advance Request','Fund Utilization Statement','Custom Template']) t;
revoke all on function public.begin_upload(uuid,text,uuid,text,text,text,bigint),public.finish_upload(uuid),public.save_generated(uuid,uuid,text,uuid,text,jsonb) from public;
grant execute on function public.begin_upload(uuid,text,uuid,text,text,text,bigint),public.finish_upload(uuid),public.save_generated(uuid,uuid,text,uuid,text,jsonb) to authenticated;
